import dsyconvfRook = require( './index' );


// TESTS //

const A = new Float64Array( [ 0.0, 2.0, 999.0, 0.0 ] );
const E = new Float64Array( 2 );
const IPIV = new Int32Array( [ -1, -2 ] );

// Canonical selectors and both public signatures return a numeric status:
dsyconvfRook( 'row-major', 'upper', 'convert', 2, A, 2, E, IPIV ); // $ExpectType number
dsyconvfRook( 'column-major', 'lower', 'revert', 2, A, 2, E, IPIV ); // $ExpectType number
dsyconvfRook.ndarray( 'upper', 'convert', 2, A, 2, 1, 0, E, 1, 0, IPIV, 1, 0 ); // $ExpectType number
dsyconvfRook.ndarray( 'lower', 'revert', 2, A, -2, -1, 3, E, -1, 1, IPIV, -1, 1 ); // $ExpectType number

// Unsupported selectors remain a compile-time error:
dsyconvfRook( 'F', 'upper', 'convert', 2, A, 2, E, IPIV ); // $ExpectError
dsyconvfRook( 'row-major', 'all', 'convert', 2, A, 2, E, IPIV ); // $ExpectError
dsyconvfRook( 'row-major', 'upper', 'C', 2, A, 2, E, IPIV ); // $ExpectError
dsyconvfRook.ndarray( 'all', 'convert', 2, A, 2, 1, 0, E, 1, 0, IPIV, 1, 0 ); // $ExpectError
dsyconvfRook.ndarray( 'upper', 'R', 2, A, 2, 1, 0, E, 1, 0, IPIV, 1, 0 ); // $ExpectError

// Each required argument must have its declared type:
dsyconvfRook( false, 'upper', 'convert', 2, A, 2, E, IPIV ); // $ExpectError
dsyconvfRook( 'row-major', false, 'convert', 2, A, 2, E, IPIV ); // $ExpectError
dsyconvfRook( 'row-major', 'upper', false, 2, A, 2, E, IPIV ); // $ExpectError
dsyconvfRook( 'row-major', 'upper', 'convert', false, A, 2, E, IPIV ); // $ExpectError
dsyconvfRook( 'row-major', 'upper', 'convert', 2, [], 2, E, IPIV ); // $ExpectError
dsyconvfRook( 'row-major', 'upper', 'convert', 2, A, false, E, IPIV ); // $ExpectError
dsyconvfRook( 'row-major', 'upper', 'convert', 2, A, 2, [], IPIV ); // $ExpectError
dsyconvfRook( 'row-major', 'upper', 'convert', 2, A, 2, E, [] ); // $ExpectError

// Missing or extra arguments are rejected:
dsyconvfRook(); // $ExpectError
dsyconvfRook( 'row-major' ); // $ExpectError
dsyconvfRook( 'row-major', 'upper' ); // $ExpectError
dsyconvfRook( 'row-major', 'upper', 'convert' ); // $ExpectError
dsyconvfRook( 'row-major', 'upper', 'convert', 2 ); // $ExpectError
dsyconvfRook( 'row-major', 'upper', 'convert', 2, A ); // $ExpectError
dsyconvfRook( 'row-major', 'upper', 'convert', 2, A, 2 ); // $ExpectError
dsyconvfRook( 'row-major', 'upper', 'convert', 2, A, 2, E ); // $ExpectError
dsyconvfRook( 'row-major', 'upper', 'convert', 2, A, 2, E, IPIV, 0 ); // $ExpectError

dsyconvfRook.ndarray( false, 'convert', 2, A, 2, 1, 0, E, 1, 0, IPIV, 1, 0 ); // $ExpectError
dsyconvfRook.ndarray( 'upper', false, 2, A, 2, 1, 0, E, 1, 0, IPIV, 1, 0 ); // $ExpectError
dsyconvfRook.ndarray( 'upper', 'convert', false, A, 2, 1, 0, E, 1, 0, IPIV, 1, 0 ); // $ExpectError
dsyconvfRook.ndarray( 'upper', 'convert', 2, [], 2, 1, 0, E, 1, 0, IPIV, 1, 0 ); // $ExpectError
dsyconvfRook.ndarray( 'upper', 'convert', 2, A, false, 1, 0, E, 1, 0, IPIV, 1, 0 ); // $ExpectError
dsyconvfRook.ndarray( 'upper', 'convert', 2, A, 2, false, 0, E, 1, 0, IPIV, 1, 0 ); // $ExpectError
dsyconvfRook.ndarray( 'upper', 'convert', 2, A, 2, 1, false, E, 1, 0, IPIV, 1, 0 ); // $ExpectError
dsyconvfRook.ndarray( 'upper', 'convert', 2, A, 2, 1, 0, [], 1, 0, IPIV, 1, 0 ); // $ExpectError
dsyconvfRook.ndarray( 'upper', 'convert', 2, A, 2, 1, 0, E, false, 0, IPIV, 1, 0 ); // $ExpectError
dsyconvfRook.ndarray( 'upper', 'convert', 2, A, 2, 1, 0, E, 1, false, IPIV, 1, 0 ); // $ExpectError
dsyconvfRook.ndarray( 'upper', 'convert', 2, A, 2, 1, 0, E, 1, 0, [], 1, 0 ); // $ExpectError
dsyconvfRook.ndarray( 'upper', 'convert', 2, A, 2, 1, 0, E, 1, 0, IPIV, false, 0 ); // $ExpectError
dsyconvfRook.ndarray( 'upper', 'convert', 2, A, 2, 1, 0, E, 1, 0, IPIV, 1, false ); // $ExpectError

// Missing or extra arguments are rejected:
dsyconvfRook.ndarray(); // $ExpectError
dsyconvfRook.ndarray( 'upper' ); // $ExpectError
dsyconvfRook.ndarray( 'upper', 'convert' ); // $ExpectError
dsyconvfRook.ndarray( 'upper', 'convert', 2 ); // $ExpectError
dsyconvfRook.ndarray( 'upper', 'convert', 2, A ); // $ExpectError
dsyconvfRook.ndarray( 'upper', 'convert', 2, A, 2 ); // $ExpectError
dsyconvfRook.ndarray( 'upper', 'convert', 2, A, 2, 1 ); // $ExpectError
dsyconvfRook.ndarray( 'upper', 'convert', 2, A, 2, 1, 0 ); // $ExpectError
dsyconvfRook.ndarray( 'upper', 'convert', 2, A, 2, 1, 0, E ); // $ExpectError
dsyconvfRook.ndarray( 'upper', 'convert', 2, A, 2, 1, 0, E, 1 ); // $ExpectError
dsyconvfRook.ndarray( 'upper', 'convert', 2, A, 2, 1, 0, E, 1, 0 ); // $ExpectError
dsyconvfRook.ndarray( 'upper', 'convert', 2, A, 2, 1, 0, E, 1, 0, IPIV ); // $ExpectError
dsyconvfRook.ndarray( 'upper', 'convert', 2, A, 2, 1, 0, E, 1, 0, IPIV, 1 ); // $ExpectError
dsyconvfRook.ndarray( 'upper', 'convert', 2, A, 2, 1, 0, E, 1, 0, IPIV, 1, 0, 0 ); // $ExpectError
